using Microsoft.EntityFrameworkCore;
namespace CasaDomotica.Home.Infrastructure.Runtime;
public sealed class HomeDb(DbContextOptions<HomeDb> options) : DbContext(options)
{
    public DbSet<DeviceRow> Devices => Set<DeviceRow>();
    public DbSet<LightRow> Lights => Set<LightRow>();
    public DbSet<ResourceRow> Resources => Set<ResourceRow>();
    public DbSet<CommandRow> Commands => Set<CommandRow>();
    public DbSet<InboxRow> Inbox => Set<InboxRow>();
    public DbSet<OutboxRow> Outbox => Set<OutboxRow>();
    public DbSet<CaptureJobRow> CaptureJobs => Set<CaptureJobRow>();
    public DbSet<TelemetryRow> Telemetry => Set<TelemetryRow>();
    public DbSet<VideoSessionRow> VideoSessions => Set<VideoSessionRow>();
    public DbSet<VideoSegmentRow> VideoSegments => Set<VideoSegmentRow>();
    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<DeviceRow>(e => { e.ToTable("HomeDevices"); e.HasKey(x => x.DeviceId); e.Property(x => x.DeviceId).HasMaxLength(128); e.HasIndex(x => x.HouseId); });
        model.Entity<LightRow>(e => { e.ToTable("HomeLights"); e.HasKey(x => new { x.HouseId, x.LightId }); e.Property(x => x.LightId).HasMaxLength(128); e.Property(x => x.DeviceId).HasMaxLength(128); e.Property(x => x.LightingMode).HasMaxLength(10); e.Property(x => x.LastCommandId).HasMaxLength(128); e.HasOne<DeviceRow>().WithMany().HasForeignKey(x => x.DeviceId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<ResourceRow>(e => { e.ToTable("HomeResources"); e.HasKey(x => new { x.HouseId, x.ResourceId }); e.Property(x => x.ResourceId).HasMaxLength(128); e.Property(x => x.DeviceId).HasMaxLength(128); e.Property(x => x.DeviceResourceId).HasMaxLength(128); e.Property(x => x.Kind).HasMaxLength(20); e.HasOne<DeviceRow>().WithMany().HasForeignKey(x => x.DeviceId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<CommandRow>(e => { e.ToTable("HomeCommands"); e.HasKey(x => x.CommandId); e.Property(x => x.CommandId).HasMaxLength(128); e.Property(x => x.LightId).HasMaxLength(128); e.Property(x => x.DeviceId).HasMaxLength(128); e.Property(x => x.Type).HasMaxLength(50); e.Property(x => x.RequestHash).HasMaxLength(64).IsUnicode(false); e.Property(x => x.IdempotencyKey).HasMaxLength(36); e.Property(x => x.Status).HasMaxLength(20); e.HasIndex(x => new { x.HouseId, x.IdempotencyKey }).IsUnique(); e.HasIndex(x => new { x.HouseId, x.LightId }).IsUnique().HasFilter("[Active] = 1"); });
        model.Entity<InboxRow>(e => { e.ToTable("HomeInbox"); e.HasKey(x => x.EventId); e.Property(x => x.DeviceId).HasMaxLength(128); });
        model.Entity<OutboxRow>(e => { e.ToTable("HomeOutbox"); e.HasKey(x => x.EventId); e.Property(x => x.Type).HasMaxLength(80); });
        model.Entity<CaptureJobRow>(e => { e.ToTable("HomeCaptureJobs"); e.HasKey(x => x.CaptureId); e.Property(x => x.DeviceId).HasMaxLength(128); e.Property(x => x.CommandId).HasMaxLength(128); e.Property(x => x.UploadTokenHash).HasMaxLength(64).IsUnicode(false); e.Property(x => x.UploadStatus).HasMaxLength(16); e.Property(x => x.UploadedBlobName).HasMaxLength(1024); e.Property(x => x.UploadedETag).HasMaxLength(128); e.Property(x => x.UploadedContentHash).HasMaxLength(64).IsUnicode(false); e.Property(x => x.UploadedContentType).HasMaxLength(32).IsUnicode(false); });
        model.Entity<TelemetryRow>(e => { e.ToTable("HomeTelemetry"); e.HasKey(x => x.EventId); e.Property(x => x.SensorId).HasMaxLength(128); e.Property(x => x.Type).HasMaxLength(80); e.HasIndex(x => new { x.HouseId, x.ReceivedAtUtc }); });
        model.Entity<VideoSessionRow>(e => { e.ToTable("HomeVideoSessions"); e.HasKey(x => x.SessionId); e.Property(x => x.ResourceId).HasMaxLength(128); e.Property(x => x.DeviceId).HasMaxLength(128); e.Property(x => x.CommandId).HasMaxLength(128); e.Property(x => x.IdempotencyKey).HasMaxLength(36); e.Property(x => x.CloseReason).HasMaxLength(24); e.Property(x => x.ProducerTokenHash).HasMaxLength(64).IsUnicode(false); e.HasIndex(x => x.HouseId).IsUnique().HasFilter("[Active] = 1"); e.HasIndex(x => new { x.HouseId, x.IdempotencyKey }).IsUnique(); });
        model.Entity<VideoSegmentRow>(e => { e.ToTable("HomeVideoSegments"); e.HasKey(x => new { x.SessionId, x.Sequence }); e.Property(x => x.ContentHash).HasMaxLength(64).IsUnicode(false); e.Property(x => x.State).HasMaxLength(16); e.Property(x => x.BlobName).HasMaxLength(1024); e.Property(x => x.BlobETag).HasMaxLength(128); e.Property(x => x.CleanupError).HasMaxLength(32); e.HasOne<VideoSessionRow>().WithMany().HasForeignKey(x => x.SessionId).OnDelete(DeleteBehavior.Restrict); });
    }
}
public sealed class DeviceRow { public string DeviceId { get; set; } = ""; public Guid HouseId { get; set; } public bool Enabled { get; set; } = true; public long LastSequence { get; set; } public DateTimeOffset? LastReportedAtUtc { get; set; } }
public sealed class LightRow { public Guid HouseId { get; set; } public string LightId { get; set; } = ""; public string DeviceId { get; set; } = ""; public bool? LightOn { get; set; } public string? LightingMode { get; set; } public long StateRevision { get; set; } public DateTimeOffset? AppliedAtUtc { get; set; } public DateTimeOffset? StateReportedAtUtc { get; set; } public string? LastCommandId { get; set; } }
public sealed class ResourceRow { public Guid HouseId { get; set; } public string ResourceId { get; set; } = ""; public string DeviceId { get; set; } = ""; public string DeviceResourceId { get; set; } = ""; public string Kind { get; set; } = ""; public bool Enabled { get; set; } = true; }
public sealed class CommandRow { public string CommandId { get; set; } = ""; public Guid HouseId { get; set; } public string LightId { get; set; } = ""; public string DeviceId { get; set; } = ""; public string Type { get; set; } = ""; public string PayloadJson { get; set; } = ""; public string RequestHash { get; set; } = ""; public string IdempotencyKey { get; set; } = ""; public long Sequence { get; set; } public Guid UserId { get; set; } public Guid SessionId { get; set; } public Guid CorrelationId { get; set; } public DateTimeOffset RequestedAtUtc { get; set; } public DateTimeOffset ExpiresAtUtc { get; set; } public DateTimeOffset? DispatchedAtUtc { get; set; } public string Status { get; set; } = "pending"; public string? ResultJson { get; set; } public bool Active { get; set; } = true; }
public sealed class InboxRow { public Guid EventId { get; set; } public string DeviceId { get; set; } = ""; public DateTimeOffset ReceivedAtUtc { get; set; } }
public sealed class OutboxRow { public Guid EventId { get; set; } public string Type { get; set; } = ""; public string BodyJson { get; set; } = ""; public DateTimeOffset CreatedAtUtc { get; set; } public DateTimeOffset? PublishedAtUtc { get; set; } }
public sealed class TelemetryRow { public Guid EventId { get; set; } public Guid HouseId { get; set; } public string SensorId { get; set; } = ""; public string Type { get; set; } = ""; public string PayloadJson { get; set; } = ""; public DateTimeOffset OccurredAtUtc { get; set; } public DateTimeOffset ReceivedAtUtc { get; set; } }

public sealed class CaptureJobRow { public Guid CaptureId { get; set; } public Guid HouseId { get; set; } public string DeviceId { get; set; } = ""; public string? CommandId { get; set; } public DateTimeOffset? CreatedAtUtc { get; set; } public DateTimeOffset ExpiresAtUtc { get; set; } public string? UploadTokenHash { get; set; } public string? UploadStatus { get; set; } public string? UploadedBlobName { get; set; } public string? UploadedETag { get; set; } public string? UploadedContentHash { get; set; } public string? UploadedContentType { get; set; } }
public sealed class VideoSessionRow { public Guid SessionId { get; set; } public Guid HouseId { get; set; } public string ResourceId { get; set; } = ""; public string DeviceId { get; set; } = ""; public Guid UserId { get; set; } public Guid UserSessionId { get; set; } public string IdempotencyKey { get; set; } = ""; public string CommandId { get; set; } = ""; public DateTimeOffset CreatedAtUtc { get; set; } public DateTimeOffset ExpiresAtUtc { get; set; } public DateTimeOffset? ClosedAtUtc { get; set; } public string? CloseReason { get; set; } public bool Active { get; set; } = true; public string? ProducerTokenHash { get; set; } public long LastSequence { get; set; } = -1; public long TotalBytes { get; set; } public string? PlaylistJson { get; set; } public DateTimeOffset? PlaylistUpdatedAtUtc { get; set; } }
public sealed class VideoSegmentRow { public Guid SessionId { get; set; } public long Sequence { get; set; } public string ContentHash { get; set; } = ""; public long SizeBytes { get; set; } public int DurationMs { get; set; } public string State { get; set; } = ""; public string? BlobName { get; set; } public string? BlobETag { get; set; } public DateTimeOffset CreatedAtUtc { get; set; } public DateTimeOffset? DeletedAtUtc { get; set; } public string? CleanupError { get; set; } }
